  internal static int RankStateFor(int contextRank4, int contextRun, int rankSizeHistory)
    => RankState[(contextRun << 11) | (contextRank4 << 3) | rankSizeHistory];

  internal static int RunStateFor(int contextRank0, int contextRun, int rank, int runSizeHistory)
    => RunState[(contextRank0 << 10) | (contextRun << 6) | (Math.Min(rank, 7) << 3) | Math.Min(runSizeHistory, 7)];

  internal static int StretchProbability(int probability) => Stretch[probability];

  internal static int SquashProbability(int stretched) => Squash[2048 + stretched];

  private static short[] DecodeShorts(string encoded) {
    var bytes = Convert.FromBase64String(encoded);
    if ((bytes.Length & 1) != 0)
      throw new InvalidDataException("BSC: invalid generated QLFC short table");
    var result = new short[bytes.Length / sizeof(short)];
    for (var i = 0; i < result.Length; ++i)
      result[i] = BinaryPrimitives.ReadInt16LittleEndian(bytes.AsSpan(i * sizeof(short), sizeof(short)));
    return result;
  }
